-- +goose Up
-- Users are created on first sign-in from the identity provider's subject.
CREATE TABLE users (
    id           UUID PRIMARY KEY,
    subject      TEXT        NOT NULL UNIQUE, -- OIDC "sub"
    email        TEXT,
    display_name TEXT,
    created_at   TIMESTAMPTZ NOT NULL,
    updated_at   TIMESTAMPTZ NOT NULL
);

-- Mirrors the app's Trip aggregate. IDs are generated by the client (UUIDv4)
-- so offline-created trips keep their identity when synced.
CREATE TABLE trips (
    id              UUID PRIMARY KEY,
    owner_id        UUID        NOT NULL REFERENCES users (id),
    title           TEXT        NOT NULL CHECK (length(btrim(title)) > 0),
    description     TEXT,
    start_date      DATE,
    end_date        DATE,
    departure_time  TEXT CHECK (departure_time ~ '^([01][0-9]|2[0-3]):[0-5][0-9]$'),
    dates_confirmed BOOLEAN     NOT NULL DEFAULT FALSE,
    time_zone       TEXT        NOT NULL,
    traveler_count  INTEGER     NOT NULL DEFAULT 1 CHECK (traveler_count BETWEEN 1 AND 999),
    currency        CHAR(3),
    total_budget    NUMERIC(14, 2) CHECK (total_budget >= 0),
    travel_style    TEXT,
    stage           TEXT        NOT NULL DEFAULT 'planning',
    archived        BOOLEAN     NOT NULL DEFAULT FALSE,
    version         BIGINT      NOT NULL DEFAULT 1, -- optimistic concurrency (ETag)
    created_at      TIMESTAMPTZ NOT NULL,
    updated_at      TIMESTAMPTZ NOT NULL,
    CHECK (end_date IS NULL OR start_date IS NOT NULL),
    CHECK (end_date IS NULL OR end_date >= start_date)
);

CREATE TABLE trip_members (
    trip_id    UUID        NOT NULL REFERENCES trips (id) ON DELETE CASCADE,
    user_id    UUID        NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    role       TEXT        NOT NULL CHECK (role IN ('owner', 'editor', 'viewer')),
    created_at TIMESTAMPTZ NOT NULL,
    PRIMARY KEY (trip_id, user_id)
);

CREATE INDEX trip_members_user_idx ON trip_members (user_id);

-- +goose Down
DROP TABLE trip_members;
DROP TABLE trips;
DROP TABLE users;
